SELECT f49.subject_id AS risk_score, f49.subject_id AS survivor_los, COUNT(DISTINCT mc.hadm_id)::FLOAT / NULLIF(COUNT(DISTINCT dc.hadm_id), 0) AS major_complication_rate, COUNT(DISTINCT s.hadm_id)::FLOAT / NULLIF(COUNT(DISTINCT hc.hadm_id), 0) AS survival_rate, percent_rank() OVER (ORDER BY f49.subject_id) AS percentile_rank FROM f49 JOIN hc ON f49.subject_id = hc.subject_id JOIN dc ON f49.subject_id = dc.subject_id JOIN ic ON f49.subject_id = ic.subject_id JOIN mc ON f49.subject_id = mc.subject_id JOIN s ON f49.subject_id = s.subject_id GROUP BY f49.subject_id ORDER BY f49.subject_id NULLS LAST;